<script setup>
import { computed, nextTick, onMounted, reactive, ref, toRaw } from 'vue';
import { RouterLink } from 'vue-router';

import { apiClient, authSession } from '../lib/auth/index.js';
import { useWorkspaceLiveRefresh } from '../lib/live/live-refresh.js';
import { timeEntryInvoiceLabel } from '../lib/projects/project-billing.js';

const emptyWorkspace = () => ({ accountingPeriods: [], allocations: [], analysis: { financialPerformance: [], forecasts: [], levelingRecommendations: [], scenarios: [], skillMatches: [], weekly: [] }, calendarEntries: [], canManageFinance: false, canManageResources: false, capacity: [], exchangeRates: [], expenseReceipts: [], expenses: [], financePolicies: [], financialEntries: [], financialRollup: { byCurrency: {}, byKind: {}, expenseByCurrency: {} }, pools: [], projects: [], resourceRates: [], resources: [], timeEntries: [], timeRollup: { approvedHours: 0, submittedHours: 0 }, timesheetPeriods: [], total: 0 });
const workspace = ref(emptyWorkspace()); const loading = ref(true); const errorMessage = ref(''); const activeTab = ref('finance');
// Finance pickers need every resource, so load the whole directory (the API caps a page at 200).
const filters = reactive({ limit: 200, offset: 0, projectId: '', query: '', reportingCurrency: 'USD', scenario: 'baseline', status: '' });
const editor = reactive({ kind: '', mode: 'create', recordId: '', values: {} });
const EDITOR_TITLES = { accountingPeriod: 'accounting period', exchangeRate: 'FX rate', expense: 'expense', expenseReceipt: 'receipt', financePolicy: 'control policy', financial: 'ledger entry', resourceRate: 'rate', time: 'time entry', timesheetPeriod: 'timesheet period' };
const deleteTarget = reactive({ id: '', kind: '', title: '', version: 0 });
const editorDialog = ref(null); const deleteDialog = ref(null);
const token = computed(() => authSession.state.token);
const resourceMap = computed(() => new Map(workspace.value.resources.map((item) => [item.id, item])));
const projectMap = computed(() => new Map(workspace.value.projects.map((item) => [item.id, item])));
// People see only their own time, and change or delete it while it is submitted and its period is open.
// Time on an invoice stays as billed, for everyone.
const canChangeTime = (item) => !item.invoiced && (workspace.value.canManageResources || (item.status === 'submitted' && (!item.periodId || workspace.value.timesheetPeriods.find((period) => period.id === item.periodId)?.status === 'open')));
const timeActions = computed(() => workspace.value.timeEntries.some(canChangeTime));

// `quiet` reloads after someone else's change: the page stays as it is while it loads, and on
// failure. The latest load wins, so a reload never overwrites newer filters or another page.
let loadSequence = 0;
async function loadWorkspace({ quiet = false } = {}) {
  const sequence = ++loadSequence;
  if (!quiet) { loading.value = true; errorMessage.value = ''; }
  try { const result = await (quiet ? apiClient.passive : apiClient).getResourceFinanceWorkspace(filters, token.value); if (sequence === loadSequence) workspace.value = { ...emptyWorkspace(), ...result, analysis: { ...emptyWorkspace().analysis, ...(result.analysis ?? {}) } }; }
  catch (error) { if (!quiet && sequence === loadSequence) errorMessage.value = error.message ?? 'Unable to load finance.'; }
  finally { if (!quiet && sequence === loadSequence) loading.value = false; }
}
function today() { return new Date().toISOString().slice(0, 10); }
function plusDays(days, from = today()) { const value = new Date(`${from}T00:00:00.000Z`); value.setUTCDate(value.getUTCDate() + days); return value.toISOString().slice(0, 10); }
function blank(kind) {
  if (kind === 'pool') return { description: '', managerId: null, name: '', status: 'active' };
  if (kind === 'resource') return { billRate: 0, capacityHoursPerWeek: 40, costRate: 0, currency: 'USD', location: '', name: '', poolId: workspace.value.pools[0]?.id ?? null, rolesText: '', skillsText: '', status: 'active', userId: null };
  if (kind === 'calendar') return { endDate: today(), entryType: 'leave', hoursPerDay: 8, note: '', resourceId: workspace.value.resources[0]?.id ?? '', startDate: today(), status: 'approved', timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC', weekdays: [1, 2, 3, 4, 5] };
  if (kind === 'allocation') return { allocationPercent: 100, endDate: plusDays(90), hoursPerWeek: 40, projectId: workspace.value.projects[0]?.id ?? '', resourceId: workspace.value.resources[0]?.id ?? '', role: '', scenario: filters.scenario || 'baseline', startDate: today(), status: 'proposed' };
  if (kind === 'accountingPeriod') { const value = new Date(); const startDate = `${value.getUTCFullYear()}-${String(value.getUTCMonth() + 1).padStart(2, '0')}-01`; const end = new Date(Date.UTC(value.getUTCFullYear(), value.getUTCMonth() + 1, 0)).toISOString().slice(0, 10); return { endDate: end, fiscalYear: value.getUTCFullYear(), name: value.toLocaleString(undefined, { month: 'long', timeZone: 'UTC', year: 'numeric' }), periodNumber: value.getUTCMonth() + 1, startDate, status: 'open' }; }
  if (kind === 'financePolicy') return { actualCostVariancePercent: 0, expenseApprovalAmount: 0, forecastVariancePercent: 0, minimumMarginPercent: 0, name: '', projectId: filters.projectId || null, status: 'active' };
  if (kind === 'financial') return { amount: 0, category: '', currency: 'USD', effectiveDate: today(), entryKind: 'budget', note: '', projectId: workspace.value.projects[0]?.id ?? '', sourceId: null, sourceType: 'manual', status: 'draft' };
  if (kind === 'time') return { billable: false, hours: 8, note: '', periodId: workspace.value.timesheetPeriods.find((item) => item.status === 'open' && item.startDate <= today() && item.endDate >= today())?.id ?? null, projectId: workspace.value.projects[0]?.id ?? '', resourceId: workspace.value.resources[0]?.id ?? '', status: 'submitted', workDate: today(), workItemId: null };
  if (kind === 'resourceRate') return { billRate: 0, costRate: 0, currency: 'USD', effectiveEnd: null, effectiveStart: today(), resourceId: workspace.value.resources[0]?.id ?? '', status: 'draft' };
  if (kind === 'timesheetPeriod') { const latestEnd = [...workspace.value.timesheetPeriods].sort((left, right) => right.endDate.localeCompare(left.endDate))[0]?.endDate; const startDate = latestEnd ? plusDays(1, latestEnd) : today(); return { approvalDueDate: null, endDate: plusDays(6, startDate), name: '', startDate, status: 'open' }; }
  if (kind === 'expenseReceipt') return { contentBase64: '', contentType: 'application/pdf', expenseId: workspace.value.expenses[0]?.id ?? '', fileName: '' };
  if (kind === 'exchangeRate') return { baseCurrency: 'USD', effectiveDate: today(), quoteCurrency: 'EUR', rate: 1, source: 'manual', status: 'draft' };
  return { amount: 0, category: '', currency: 'USD', expenseDate: today(), note: '', projectId: workspace.value.projects[0]?.id ?? '', receiptReference: '', resourceId: workspace.value.resources[0]?.id ?? null, status: 'submitted' };
}
async function openEditor(kind, record = null) {
  editor.kind = kind; editor.mode = record ? 'edit' : 'create'; editor.recordId = record?.id ?? '';
  editor.values = record ? structuredClone(toRaw(record)) : blank(kind);
  if (kind === 'resource' && record) {
    editor.values.rolesText = (record.roles ?? []).join(', ');
    editor.values.skillsText = (record.skills ?? []).map((skill) => `${skill.name}:${skill.level}`).join(', ');
  }
  await nextTick(); editorDialog.value?.showModal();
}
function closeEditor() { editorDialog.value?.close(); }
function cleanValues() {
  const values = { ...editor.values };
  for (const key of ['createdAt', 'updatedAt', 'tenantId', 'id']) delete values[key];
  if (editor.mode === 'edit') values.expectedVersion = editor.values.version;
  delete values.version;
  if (editor.kind === 'resource') {
    values.roles = values.rolesText.split(',').map((value) => value.trim()).filter(Boolean);
    values.skills = values.skillsText.split(',').map((value) => { const [name, level] = value.split(':'); return { level: Math.max(1, Math.min(5, Number(level) || 3)), name: name.trim() }; }).filter((skill) => skill.name);
    delete values.rolesText; delete values.skillsText;
  }
  for (const key of ['approvalDueDate', 'effectiveEnd', 'periodId']) if (values[key] === '') values[key] = null;
  for (const key of ['baseCurrency', 'currency', 'quoteCurrency']) if (values[key]) values[key] = String(values[key]).toUpperCase();
  return values;
}
async function saveEditor() {
  errorMessage.value = '';
  const values = cleanValues(); const id = editor.recordId; const edit = editor.mode === 'edit';
  try {
    if (editor.kind === 'pool') edit ? await apiClient.updateResourcePool(id, values, token.value) : await apiClient.createResourcePool(values, token.value);
    if (editor.kind === 'resource') edit ? await apiClient.updateEnterpriseResource(id, values, token.value) : await apiClient.createEnterpriseResource(values, token.value);
    if (editor.kind === 'calendar') edit ? await apiClient.updateResourceCalendarEntry(id, values, token.value) : await apiClient.createResourceCalendarEntry(values, token.value);
    if (editor.kind === 'allocation') edit ? await apiClient.updateResourceAllocation(id, values, token.value) : await apiClient.createResourceAllocation(values, token.value);
    if (editor.kind === 'accountingPeriod') edit ? await apiClient.updateAccountingPeriod(id, values, token.value) : await apiClient.createAccountingPeriod(values, token.value);
    if (editor.kind === 'financePolicy') edit ? await apiClient.updateFinancePolicy(id, values, token.value) : await apiClient.createFinancePolicy(values, token.value);
    if (editor.kind === 'financial') edit ? await apiClient.updateProjectFinancialEntry(id, values, token.value) : await apiClient.createProjectFinancialEntry(values, token.value);
    if (editor.kind === 'time') edit ? await apiClient.updateProjectTimeEntry(id, values, token.value) : await apiClient.createProjectTimeEntry(values, token.value);
    if (editor.kind === 'expense') edit ? await apiClient.updateProjectExpense(id, values, token.value) : await apiClient.createProjectExpense(values, token.value);
    if (editor.kind === 'resourceRate') edit ? await apiClient.updateResourceRate(id, values, token.value) : await apiClient.createResourceRate(values, token.value);
    if (editor.kind === 'timesheetPeriod') edit ? await apiClient.updateTimesheetPeriod(id, values, token.value) : await apiClient.createTimesheetPeriod(values, token.value);
    if (editor.kind === 'expenseReceipt') edit ? await apiClient.updateExpenseReceipt(id, values, token.value) : await apiClient.uploadExpenseReceipt(values.expenseId, { contentBase64: values.contentBase64, contentType: values.contentType, fileName: values.fileName }, token.value);
    if (editor.kind === 'exchangeRate') edit ? await apiClient.updateExchangeRate(id, values, token.value) : await apiClient.createExchangeRate(values, token.value);
    closeEditor(); await loadWorkspace();
  } catch (error) { errorMessage.value = error.message ?? 'Unable to save record.'; }
}
async function openDelete(kind, record, title) { Object.assign(deleteTarget, { id: record.id, kind, title, version: record.version }); await nextTick(); deleteDialog.value?.showModal(); }
async function deleteRecord() {
  const { id, kind, version } = deleteTarget;
  try {
    if (kind === 'pool') await apiClient.deleteResourcePool(id, version, token.value);
    if (kind === 'resource') await apiClient.deleteEnterpriseResource(id, version, token.value);
    if (kind === 'calendar') await apiClient.deleteResourceCalendarEntry(id, version, token.value);
    if (kind === 'allocation') await apiClient.deleteResourceAllocation(id, version, token.value);
    if (kind === 'accountingPeriod') await apiClient.deleteAccountingPeriod(id, version, token.value);
    if (kind === 'financePolicy') await apiClient.deleteFinancePolicy(id, version, token.value);
    if (kind === 'financial') await apiClient.deleteProjectFinancialEntry(id, version, token.value);
    if (kind === 'time') await apiClient.deleteProjectTimeEntry(id, version, token.value);
    if (kind === 'expense') await apiClient.deleteProjectExpense(id, version, token.value);
    if (kind === 'resourceRate') await apiClient.deleteResourceRate(id, version, token.value);
    if (kind === 'timesheetPeriod') await apiClient.deleteTimesheetPeriod(id, version, token.value);
    if (kind === 'expenseReceipt') await apiClient.deleteExpenseReceipt(id, version, token.value);
    if (kind === 'exchangeRate') await apiClient.deleteExchangeRate(id, version, token.value);
    deleteDialog.value?.close(); await loadWorkspace();
  } catch (error) { errorMessage.value = error.message ?? 'Unable to delete record.'; deleteDialog.value?.close(); }
}
async function selectReceiptFile(event) {
  const file = event.target.files?.[0]; if (!file) return;
  editor.values.fileName = file.name; editor.values.contentType = file.type || 'application/octet-stream';
  editor.values.contentBase64 = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onerror = () => reject(reader.error); reader.onload = () => resolve(String(reader.result ?? '').split(',')[1] ?? ''); reader.readAsDataURL(file); });
}
async function downloadReceipt(item) {
  try { const { blob } = await apiClient.downloadExpenseReceipt(item.id, token.value); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = item.fileName; anchor.click(); URL.revokeObjectURL(url); }
  catch (error) { errorMessage.value = error.message ?? 'Unable to download receipt.'; }
}
function applyFilters() { filters.offset = 0; loadWorkspace(); }
function money(value, currency = 'USD') { return new Intl.NumberFormat(undefined, { currency, maximumFractionDigits: 0, style: 'currency' }).format(Number(value ?? 0)); }
onMounted(() => loadWorkspace());
// Time, allocations and finance records changed elsewhere, by people, the assistant or MCP clients.
useWorkspaceLiveRefresh(['resources'], () => {
  if (!loading.value) loadWorkspace({ quiet: true });
});
</script>

<template>
  <main class="resource-page">
    <header class="resource-header">
      <div><h1>Finance</h1><p>Project ledgers, budgets, rates, time and expenses. People, skills and allocations are on <RouterLink :to="{ name: 'resources' }">Resources</RouterLink>.</p></div>
      <div class="header-actions">
        <button v-if="workspace.resources.length" class="btn btn-sm btn-outline-primary" type="button" @click="openEditor('time')"><i class="bi bi-clock" aria-hidden="true"></i> Add time</button>
        <button v-if="workspace.canManageFinance" class="btn btn-sm btn-primary" type="button" @click="openEditor('financial')"><i class="bi bi-cash-stack" aria-hidden="true"></i> Add ledger entry</button>
      </div>
    </header>
    <div v-if="errorMessage" class="alert alert-danger" role="alert">{{ errorMessage }}</div>
    <section class="resource-metrics" aria-label="Finance summary">
      <article><span>Ledger entries</span><strong>{{ workspace.financialEntries.length }}</strong></article>
      <article><span>Expenses</span><strong>{{ workspace.expenses.length }}</strong></article>
      <article><span>Approved hours</span><strong>{{ workspace.timeRollup.approvedHours }}</strong></article>
      <article><span>Submitted hours</span><strong>{{ workspace.timeRollup.submittedHours }}</strong></article>
    </section>
    <form class="resource-filters" @submit.prevent="applyFilters">
      <label>Project<select v-model="filters.projectId" class="form-select form-select-sm"><option value="">All visible projects</option><option v-for="project in workspace.projects" :key="project.id" :value="project.id">{{ project.name }}</option></select></label>
      <label v-if="workspace.canManageFinance">Reporting currency<input v-model.trim="filters.reportingCurrency" class="form-control form-control-sm" maxlength="3" /></label>
      <button class="btn btn-sm btn-outline-secondary" type="submit"><i class="bi bi-funnel" aria-hidden="true"></i> Apply</button>
    </form>
    <nav class="resource-tabs" aria-label="Finance sections">
      <button v-for="tab in [['finance','Ledger & controls'],['time','Time & expenses']]" :key="tab[0]" :class="{ active: activeTab === tab[0] }" type="button" @click="activeTab = tab[0]">{{ tab[1] }}</button>
    </nav>
    <p v-if="loading" class="empty-state" role="status">Loading finance…</p>
    <template v-else>
      <section v-if="activeTab === 'finance'" aria-labelledby="finance-title">
        <div class="section-heading"><h2 id="finance-title">Project financials</h2><div v-if="workspace.canManageFinance" class="section-actions"><button class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('financial')">Add ledger entry</button><button class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('resourceRate')">Add rate</button><button class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('exchangeRate')">Add FX rate</button><button class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('accountingPeriod')">Add accounting period</button><button class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('financePolicy')">Add control policy</button></div></div>
        <div v-if="!workspace.canManageFinance" class="empty-state">Financial details require manager or administrator access.</div>
        <template v-else>
          <div class="split-tables finance-controls"><div class="table-responsive"><table class="table table-sm"><caption>Accounting periods</caption><thead><tr><th>Period</th><th>Dates</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in workspace.accountingPeriods" :key="item.id"><td>{{ item.fiscalYear }} / {{ item.periodNumber }}<small>{{ item.name }}</small></td><td>{{ item.startDate }} – {{ item.endDate }}</td><td>{{ item.status }}</td><td><div class="row-actions"><button aria-label="Edit accounting period" type="button" @click="openEditor('accountingPeriod', item)"><i class="bi bi-pencil"></i></button><button aria-label="Delete accounting period" type="button" @click="openDelete('accountingPeriod', item, item.name)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="workspace.accountingPeriods.length === 0"><td colspan="4" class="empty-state">No accounting periods.</td></tr></tbody></table></div><div class="table-responsive"><table class="table table-sm"><caption>Financial control policies</caption><thead><tr><th>Policy / scope</th><th>Thresholds</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in workspace.financePolicies" :key="item.id"><td>{{ item.name }}<small>{{ item.projectId ? projectMap.get(item.projectId)?.name ?? item.projectId : 'Tenant default' }}</small></td><td>Actual {{ item.actualCostVariancePercent }}% · forecast {{ item.forecastVariancePercent }}%<small>Margin {{ item.minimumMarginPercent }}% · admin approval {{ money(item.expenseApprovalAmount) }}</small></td><td>{{ item.status }}</td><td><div class="row-actions"><button aria-label="Edit financial control policy" type="button" @click="openEditor('financePolicy', item)"><i class="bi bi-pencil"></i></button><button aria-label="Delete financial control policy" type="button" @click="openDelete('financePolicy', item, item.name)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="workspace.financePolicies.length === 0"><td colspan="4" class="empty-state">No persisted control policies.</td></tr></tbody></table></div></div>
          <div class="financial-performance"><article v-for="item in workspace.analysis.financialPerformance" :key="`${item.projectId}-${item.currency}`"><span>{{ projectMap.get(item.projectId)?.name ?? item.projectId }} · {{ item.currency }}</span><strong>{{ money(item.margin, item.currency) }} margin</strong><small>{{ item.marginPercent ?? '—' }}% · CPI {{ item.costPerformanceIndex ?? '—' }} · SPI {{ item.schedulePerformanceIndex ?? '—' }} · EAC {{ money(item.estimateAtCompletion, item.currency) }}</small><small>Policy: {{ item.thresholdPolicy?.name ?? 'Default zero-tolerance policy' }}</small><small v-if="Object.values(item.thresholds).some(Boolean)" class="text-danger">Threshold attention required</small></article></div>
          <div class="table-responsive"><table class="table table-sm"><caption>Project ledger</caption><thead><tr><th>Project</th><th>Kind</th><th>Category</th><th>Effective</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in workspace.financialEntries" :key="item.id"><td>{{ projectMap.get(item.projectId)?.name ?? item.projectId }}</td><td>{{ item.entryKind.replace('_', ' ') }}</td><td>{{ item.category || '—' }}</td><td>{{ item.effectiveDate }}</td><td>{{ money(item.amount, item.currency) }}</td><td>{{ item.status }}</td><td><div v-if="!['posted','void'].includes(item.status)" class="row-actions"><button aria-label="Edit financial entry" type="button" @click="openEditor('financial', item)"><i class="bi bi-pencil"></i></button><button aria-label="Delete financial entry" type="button" @click="openDelete('financial', item, item.entryKind)"><i class="bi bi-trash"></i></button></div><span v-else>Immutable</span></td></tr><tr v-if="workspace.financialEntries.length === 0"><td colspan="7" class="empty-state">No financial ledger entries.</td></tr></tbody></table></div>
          <div class="split-tables"><div class="table-responsive"><table class="table table-sm"><caption>Effective resource rates</caption><thead><tr><th>Resource</th><th>Effective</th><th>Cost / bill</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in workspace.resourceRates" :key="item.id"><td>{{ resourceMap.get(item.resourceId)?.name ?? item.resourceId }}</td><td>{{ item.effectiveStart }} – {{ item.effectiveEnd ?? 'open' }}</td><td>{{ money(item.costRate, item.currency) }} / {{ money(item.billRate, item.currency) }}</td><td>{{ item.status }}</td><td><div class="row-actions"><button aria-label="Edit resource rate" type="button" @click="openEditor('resourceRate', item)"><i class="bi bi-pencil"></i></button><button aria-label="Delete resource rate" type="button" @click="openDelete('resourceRate', item, 'resource rate')"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="workspace.resourceRates.length === 0"><td colspan="5" class="empty-state">No rate history.</td></tr></tbody></table></div>
          <div class="table-responsive"><table class="table table-sm"><caption>Exchange rates</caption><thead><tr><th>Pair</th><th>Rate</th><th>Effective</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in workspace.exchangeRates" :key="item.id"><td>{{ item.baseCurrency }}/{{ item.quoteCurrency }}</td><td>{{ item.rate }}</td><td>{{ item.effectiveDate }}<small>{{ item.source }}</small></td><td>{{ item.status }}</td><td><div class="row-actions"><button aria-label="Edit exchange rate" type="button" @click="openEditor('exchangeRate', item)"><i class="bi bi-pencil"></i></button><button aria-label="Delete exchange rate" type="button" @click="openDelete('exchangeRate', item, `${item.baseCurrency}/${item.quoteCurrency}`)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="workspace.exchangeRates.length === 0"><td colspan="5" class="empty-state">No exchange rates.</td></tr></tbody></table></div></div>
        </template>
      </section>
      <section v-if="activeTab === 'time'" aria-labelledby="time-title"><div class="section-heading"><h2 id="time-title">Time & expenses</h2><div class="section-actions"><button v-if="workspace.resources.length" class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('time')">Add time</button><button v-if="workspace.canManageResources" class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('timesheetPeriod')">Add period</button><button v-if="workspace.canManageFinance" class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('expense')">Add expense</button><button v-if="workspace.canManageFinance && workspace.expenses.length" class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('expenseReceipt')">Upload receipt</button></div></div>
        <div class="table-responsive"><table class="table table-sm"><caption>Timesheet periods</caption><thead><tr><th>Name</th><th>Dates</th><th>Approval due</th><th>Status</th><th v-if="workspace.canManageResources">Actions</th></tr></thead><tbody><tr v-for="item in workspace.timesheetPeriods" :key="item.id"><td>{{ item.name }}</td><td>{{ item.startDate }} – {{ item.endDate }}</td><td>{{ item.approvalDueDate ?? '—' }}</td><td>{{ item.status }}</td><td v-if="workspace.canManageResources"><div class="row-actions"><button aria-label="Edit timesheet period" type="button" @click="openEditor('timesheetPeriod', item)"><i class="bi bi-pencil"></i></button><button aria-label="Delete timesheet period" type="button" @click="openDelete('timesheetPeriod', item, item.name)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="workspace.timesheetPeriods.length === 0"><td colspan="5" class="empty-state">No timesheet periods.</td></tr></tbody></table></div>
        <div class="split-tables"><div class="table-responsive"><table class="table table-sm"><caption>Time entries</caption><thead><tr><th>Resource</th><th>Project / date</th><th>Hours</th><th>Status</th><th v-if="timeActions">Actions</th></tr></thead><tbody><tr v-for="item in workspace.timeEntries" :key="item.id"><td>{{ resourceMap.get(item.resourceId)?.name ?? item.resourceId }}</td><td>{{ projectMap.get(item.projectId)?.name ?? item.projectId }}<small>{{ item.workDate }}</small></td><td>{{ item.hours }}</td><td>{{ item.status }}<small v-if="item.invoiced" class="time-invoice" data-testid="time-entry-invoice"><i class="bi bi-lock-fill" aria-hidden="true"></i> <a v-if="item.invoice?.url" :href="item.invoice.url" target="_blank" rel="noopener noreferrer">{{ timeEntryInvoiceLabel(item) }}</a><template v-else>{{ timeEntryInvoiceLabel(item) }}</template><span class="visually-hidden">, invoiced and read-only</span></small></td><td v-if="timeActions"><div v-if="canChangeTime(item)" class="row-actions"><button aria-label="Edit time entry" type="button" @click="openEditor('time', item)"><i class="bi bi-pencil"></i></button><button aria-label="Delete time entry" type="button" @click="openDelete('time', item, `${item.hours} hour entry`)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="workspace.timeEntries.length === 0"><td colspan="5" class="empty-state">No visible time entries.</td></tr></tbody></table></div><div v-if="workspace.canManageFinance" class="table-responsive"><table class="table table-sm"><caption>Expenses</caption><thead><tr><th>Project / date</th><th>Category</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in workspace.expenses" :key="item.id"><td>{{ projectMap.get(item.projectId)?.name ?? item.projectId }}<small>{{ item.expenseDate }}</small></td><td>{{ item.category }}</td><td>{{ money(item.amount, item.currency) }}</td><td>{{ item.status }}</td><td><div class="row-actions"><button aria-label="Edit expense" type="button" @click="openEditor('expense', item)"><i class="bi bi-pencil"></i></button><button aria-label="Delete expense" type="button" @click="openDelete('expense', item, item.category)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="workspace.expenses.length === 0"><td colspan="5" class="empty-state">No expenses.</td></tr></tbody></table></div></div>
        <div v-if="workspace.canManageFinance" class="table-responsive"><table class="table table-sm"><caption>Receipt objects</caption><thead><tr><th>Expense</th><th>File</th><th>Integrity</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in workspace.expenseReceipts" :key="item.id"><td>{{ workspace.expenses.find(expense => expense.id === item.expenseId)?.category ?? item.expenseId }}</td><td>{{ item.fileName }}<small>{{ item.contentType }} · {{ item.sizeBytes.toLocaleString() }} bytes</small></td><td><code>{{ item.sha256.slice(0, 12) }}…</code></td><td>{{ item.status }}</td><td><div class="row-actions"><button aria-label="Download expense receipt" type="button" @click="downloadReceipt(item)"><i class="bi bi-download"></i></button><button aria-label="Delete expense receipt" type="button" @click="openDelete('expenseReceipt', item, item.fileName)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="workspace.expenseReceipts.length === 0"><td colspan="5" class="empty-state">No receipt objects.</td></tr></tbody></table></div>
      </section>
    </template>

    <dialog ref="editorDialog" class="resource-dialog" @cancel.prevent="closeEditor"><form method="dialog" @submit.prevent="saveEditor"><header><h2>{{ editor.mode === 'edit' ? 'Edit' : 'Add' }} {{ EDITOR_TITLES[editor.kind] ?? editor.kind }}</h2><button aria-label="Close editor" type="button" @click="closeEditor"><i class="bi bi-x-lg"></i></button></header>
      <template v-if="editor.kind === 'financial'"><label>Project<select v-model="editor.values.projectId" required><option v-for="item in workspace.projects" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><div class="dialog-grid"><label>Kind<select v-model="editor.values.entryKind"><option v-for="kind in ['budget','funding','forecast','commitment','actual_cost','revenue','capitalized_cost']" :key="kind" :value="kind">{{ kind.replace('_', ' ') }}</option></select></label><label>Category<input v-model="editor.values.category" /></label><label>Amount<input v-model.number="editor.values.amount" inputmode="decimal" type="number" step="any" /></label><label>Currency<input v-model="editor.values.currency" maxlength="3" /></label><label>Effective date<input v-model="editor.values.effectiveDate" type="date" /></label><label>Status<select v-model="editor.values.status"><option value="draft">Draft</option><option value="approved">Approved</option><option value="posted">Posted (admin)</option></select></label></div><label>Note<textarea v-model="editor.values.note"></textarea></label></template>
      <template v-if="editor.kind === 'time'"><label>Resource<select v-model="editor.values.resourceId" required><option v-for="item in workspace.resources" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Project<select v-model="editor.values.projectId" required><option v-for="item in workspace.projects" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Timesheet period<select v-model="editor.values.periodId"><option :value="null">No period</option><option v-for="item in workspace.timesheetPeriods" :key="item.id" :value="item.id">{{ item.name }} · {{ item.status }}</option></select></label><div class="dialog-grid"><label>Work date<input v-model="editor.values.workDate" type="date" /></label><label>Hours<input v-model.number="editor.values.hours" min="0.25" max="24" step="0.25" type="number" /></label><label>Status<select v-model="editor.values.status"><option value="submitted">Submitted</option><option v-if="workspace.canManageResources" value="approved">Approved</option><option v-if="workspace.canManageResources" value="rejected">Rejected</option></select></label><label><input v-model="editor.values.billable" type="checkbox" /> Billable</label></div><label>Note<textarea v-model="editor.values.note"></textarea></label></template>
      <template v-if="editor.kind === 'expense'"><label>Project<select v-model="editor.values.projectId" required><option v-for="item in workspace.projects" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><div class="dialog-grid"><label>Expense date<input v-model="editor.values.expenseDate" type="date" /></label><label>Category<input v-model="editor.values.category" required /></label><label>Amount<input v-model.number="editor.values.amount" min="0" inputmode="decimal" type="number" step="any" /></label><label>Currency<input v-model="editor.values.currency" maxlength="3" /></label><label>Status<select v-model="editor.values.status"><option value="submitted">Submitted</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></label></div><label>Receipt reference<input v-model="editor.values.receiptReference" /></label><label>Note<textarea v-model="editor.values.note"></textarea></label></template>
      <template v-if="editor.kind === 'resourceRate'"><label>Resource<select v-model="editor.values.resourceId" required><option v-for="item in workspace.resources" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><div class="dialog-grid"><label>Effective start<input v-model="editor.values.effectiveStart" type="date" /></label><label>Effective end<input v-model="editor.values.effectiveEnd" type="date" /></label><label>Cost rate<input v-model.number="editor.values.costRate" min="0" inputmode="decimal" type="number" step="any" /></label><label>Bill rate<input v-model.number="editor.values.billRate" min="0" inputmode="decimal" type="number" step="any" /></label><label>Currency<input v-model.trim="editor.values.currency" maxlength="3" /></label><label>Status<select v-model="editor.values.status"><option value="draft">Draft</option><option value="approved">Approved</option><option value="retired">Retired</option></select></label></div></template>
      <template v-if="editor.kind === 'timesheetPeriod'"><label>Name<input v-model="editor.values.name" required /></label><div class="dialog-grid"><label>Start date<input v-model="editor.values.startDate" type="date" /></label><label>End date<input v-model="editor.values.endDate" type="date" /></label><label>Approval due<input v-model="editor.values.approvalDueDate" type="date" /></label><label>Status<select v-model="editor.values.status"><option value="open">Open</option><option value="locked">Locked</option><option value="closed">Closed</option></select></label></div></template>
      <template v-if="editor.kind === 'expenseReceipt'"><label>Expense<select v-model="editor.values.expenseId" required><option v-for="item in workspace.expenses" :key="item.id" :value="item.id">{{ item.category }} · {{ item.expenseDate }}</option></select></label><label>Receipt file<input accept="application/pdf,image/jpeg,image/png,image/webp" type="file" required @change="selectReceiptFile" /><small>PDF, JPEG, PNG, or WebP up to 10 MB. The server scans and hashes the object.</small></label><p v-if="editor.values.fileName">Selected: <strong>{{ editor.values.fileName }}</strong></p></template>
      <template v-if="editor.kind === 'exchangeRate'"><div class="dialog-grid"><label>Base currency<input v-model.trim="editor.values.baseCurrency" maxlength="3" required /></label><label>Quote currency<input v-model.trim="editor.values.quoteCurrency" maxlength="3" required /></label><label>Rate<input v-model.number="editor.values.rate" min="0.0000000001" step="any" type="number" /></label><label>Effective date<input v-model="editor.values.effectiveDate" type="date" /></label><label>Source<input v-model="editor.values.source" required /></label><label>Status<select v-model="editor.values.status"><option value="draft">Draft</option><option value="approved">Approved</option><option value="retired">Retired</option></select></label></div></template>
      <template v-if="editor.kind === 'accountingPeriod'"><label>Name<input v-model="editor.values.name" required /></label><div class="dialog-grid"><label>Fiscal year<input v-model.number="editor.values.fiscalYear" min="1900" max="9999" type="number" /></label><label>Period number<input v-model.number="editor.values.periodNumber" min="1" max="53" type="number" /></label><label>Start date<input v-model="editor.values.startDate" type="date" /></label><label>End date<input v-model="editor.values.endDate" type="date" /></label><label>Status<select v-model="editor.values.status"><option value="open">Open</option><option value="locked">Locked</option><option value="closed">Closed</option></select></label></div></template>
      <template v-if="editor.kind === 'financePolicy'"><label>Name<input v-model="editor.values.name" required /></label><label>Project scope<select v-model="editor.values.projectId"><option :value="null">Tenant default</option><option v-for="item in workspace.projects" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><div class="dialog-grid"><label>Actual cost tolerance (%)<input v-model.number="editor.values.actualCostVariancePercent" min="0" type="number" /></label><label>Forecast tolerance (%)<input v-model.number="editor.values.forecastVariancePercent" min="0" type="number" /></label><label>Minimum margin (%)<input v-model.number="editor.values.minimumMarginPercent" type="number" /></label><label>Admin expense approval at<input v-model.number="editor.values.expenseApprovalAmount" min="0" type="number" /></label><label>Status<select v-model="editor.values.status"><option value="active">Active</option><option value="inactive">Inactive</option></select></label></div></template>
      <footer><button class="btn btn-sm btn-outline-secondary" type="button" @click="closeEditor">Cancel</button><button class="btn btn-sm btn-primary" type="submit">Save</button></footer></form></dialog>
    <dialog ref="deleteDialog" class="resource-dialog resource-dialog--small"><form method="dialog" @submit.prevent="deleteRecord"><header><h2>Delete {{ EDITOR_TITLES[deleteTarget.kind] ?? deleteTarget.kind }}</h2></header><p>Delete <strong>{{ deleteTarget.title }}</strong>? Posted ledgers and records with dependents cannot be deleted.</p><footer><button class="btn btn-sm btn-outline-secondary" type="button" @click="deleteDialog.close()">Cancel</button><button class="btn btn-sm btn-danger" type="submit">Delete</button></footer></form></dialog>
  </main>
</template>

